5. [TestClass]
6. public sealed class StringFormatterTests
7. {
8.     private readonly StringFormatter _formatter = new();
9. 
10.     // ── FormatPhoneNumber ──────────────────────────────────────────
11. 
12.     [TestMethod]
13.     public void FormatPhoneNumber_ValidDigits_StartsWithAreaCode()
14.     {
15.         var result = _formatter.FormatPhoneNumber("2125551234");
16. 
17.         StringAssert.StartsWith(result, "(212)");
18.     }
19. 
